Action: run_sql({'query': "WITH halal_gmap_ids AS (\n    SELECT DISTINCT gmap_id FROM establishment_attributes WHERE attribute = 'Halal food'\n    UNION\n    SELECT DISTINCT gmap_id FROM establishments WHERE LOWER(name) LIKE '%halal%' OR LOWER(description) LIKE '%halal%'\n    UNION\n    SELECT DISTINCT ec.gmap_id FROM establishment_categories ec JOIN category c ON ec.category_id = c.category_id WHERE LOWER(c.category) LIKE '%halal%'\n)\nSELECT \n    c.category,\n    COUNT(DISTINCT e.gmap_id) as restaurant_count\nFROM halal_gmap_ids h\nJOIN establishments e ON h.gmap_id = e.gmap_id\nJOIN establishment_categories ec ON e.gmap_id = ec.gmap_id\nJOIN category c ON ec.category_id = c.category_id\nWHERE e.address LIKE '%Salt Lake City%' OR e.address LIKE '%West Valley City%' OR e.address LIKE '%Sandy%' OR e.address LIKE '%South Salt Lake%' OR e.address LIKE '%South Jordan%' OR e.address LIKE '%West Jordan%' OR e.address LIKE '%Midvale%' OR e.address LIKE '%Holladay%' OR e.address LIKE '%Cottonwood Heights%' OR e.address LIKE '%Millcreek%' OR e.address LIKE '%Draper%' OR e.address LIKE '%Murray%' OR e.address LIKE '%Taylorsville%' OR e.address LIKE '%Riverton%' OR e.address LIKE '%Herriman%' OR e.address LIKE '%Kearns%' OR e.address LIKE '%Magna%'\nGROUP BY c.category\nORDER BY restaurant_count DESC\nLIMIT 15;"})

