Action: run_sql({'query': "WITH halal_gmap_ids AS (\n    SELECT DISTINCT e.gmap_id\n    FROM establishments e\n    LEFT JOIN establishment_attributes ea ON e.gmap_id = ea.gmap_id\n    LEFT JOIN establishment_categories ec ON e.gmap_id = ec.gmap_id\n    LEFT JOIN category c ON ec.category_id = c.category_id\n    WHERE ea.attribute = 'Halal food' \n       OR LOWER(e.name) LIKE '%halal%' \n       OR LOWER(e.description) LIKE '%halal%'\n       OR LOWER(c.category) LIKE '%halal%'\n),\nslc_county_establishments AS (\n    SELECT \n        e.gmap_id,\n        CASE WHEN h.gmap_id IS NOT NULL THEN 'Halal Options' ELSE 'Non-Halal / Standard' END AS halal_status\n    FROM establishments e\n    LEFT JOIN halal_gmap_ids h ON e.gmap_id = h.gmap_id\n    WHERE e.address LIKE '%Salt Lake City%' OR e.address LIKE '%West Valley City%' OR e.address LIKE '%Sandy%' OR e.address LIKE '%South Salt Lake%' OR e.address LIKE '%South Jordan%' OR e.address LIKE '%West Jordan%' OR e.address LIKE '%Midvale%' OR e.address LIKE '%Holladay%' OR e.address LIKE '%Cottonwood Heights%' OR e.address LIKE '%Millcreek%' OR e.address LIKE '%Draper%' OR e.address LIKE '%Murray%' OR e.address LIKE '%Taylorsville%' OR e.address LIKE '%Riverton%' OR e.address LIKE '%Herriman%' OR e.address LIKE '%Kearns%' OR e.address LIKE '%Magna%'\n)\nSELECT halal_status, COUNT(*) as establishment_count\nFROM slc_county_establishments\nGROUP BY halal_status;"})

