Action: run_sql({'query': "WITH plant_gmap AS (\n    SELECT DISTINCT e.gmap_id\n    FROM establishments e\n    LEFT JOIN establishment_attributes ea ON e.gmap_id = ea.gmap_id\n    LEFT JOIN establishment_categories ec ON e.gmap_id = ec.gmap_id\n    LEFT JOIN category c ON ec.category_id = c.category_id\n    WHERE LOWER(c.category) LIKE '%vegetarian%' \n       OR LOWER(c.category) LIKE '%vegan%'\n       OR LOWER(ea.attribute) LIKE '%vegetarian%'\n       OR LOWER(ea.attribute) LIKE '%vegan%'\n       OR LOWER(e.name) LIKE '%veggie%'\n       OR LOWER(e.name) LIKE '%vegan%'\n       OR LOWER(e.name) LIKE '%rawtopia%'\n       OR LOWER(e.name) LIKE '%zest kitchen%'\n)\nSELECT \n    e.name,\n    e.address,\n    e.avg_rating,\n    e.num_of_reviews,\n    COALESCE(e.price, '$-$$') as price,\n    e.slchd_establishment_key\nFROM plant_gmap p\nJOIN establishments e ON p.gmap_id = e.gmap_id\nWHERE e.address LIKE '%Salt Lake City%' OR e.address LIKE '%West Valley City%' OR e.address LIKE '%Sandy%' OR e.address LIKE '%South Salt Lake%' OR e.address LIKE '%South Jordan%' OR e.address LIKE '%West Jordan%' OR e.address LIKE '%Midvale%' OR e.address LIKE '%Holladay%' OR e.address LIKE '%Cottonwood Heights%' OR e.address LIKE '%Millcreek%' OR e.address LIKE '%Murray%'\nORDER BY e.avg_rating DESC, e.num_of_reviews DESC\nLIMIT 12;"})

